const axios = require('axios')

async function igdl(url) {
  try {
    if (!url) throw new Error('URL requerida')

    const { data } = await axios.get(
      'https://api.vreden.my.id/api/v1/download/instagram',
      {
        params: { url },
        timeout: 15000,
        headers: {
          'User-Agent': 'Mozilla/5.0'
        }
      }
    )

    if (!data?.status || !data?.result) {
      throw new Error('API inválida o sin resultados')
    }

    const result = data.result

    // Tomamos solo el primer media (como quieres estilo simple)
    const media = result.data[0]

    return {
      desc: result.caption?.text || '',
      thumb: media?.thumb || null,
      dl_url: media?.url || null
    }

  } catch (err) {
    console.error('❌ igdl error:', err.message)
    throw err
  }
}

module.exports = { igdl }